SELECT p.category, CASE WHEN p.price >= 1010 THEN 'high' WHEN p.price >= 230 THEN 'mid' ELSE 'low' END AS price_bucket, COUNT(oi.unit_price) AS unit_price_count FROM order_items oi LEFT JOIN products p ON oi.product_id = p.id LEFT JOIN suppliers s ON p.supplier_id = s.id GROUP BY p.category, CASE WHEN p.price >= 1010 THEN 'high' WHEN p.price >= 230 THEN 'mid' ELSE 'low' END ORDER BY p.category;
